#include <vector>
#include <unordered_map>

class Solution {
public:
    int countSubarraysWithKUnique(std::vector<int>& nums, int k) {
        auto atMost = [&](int m) -> int {
            if (m <= 0) return 0;
            std::unordered_map<int, int> freq;
            int left = 0, ans = 0;
            for (int right = 0; right < (int)nums.size(); ++right) {
                freq[nums[right]]++;
                while ((int)freq.size() > m) {
                    if (--freq[nums[left]] == 0) {
                        freq.erase(nums[left]);
                    }
                    left++;
                }
                ans += right - left + 1;
            }
            return ans;
        };
        return atMost(k) - atMost(k - 1);
    }
};

import java.util.*;

class Solution {
    public int countSubarraysWithKUnique(int[] nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);
    }

    private int atMost(int[] nums, int m) {
        if (m <= 0) return 0;
        Map<Integer, Integer> freq = new HashMap<>();
        int left = 0, ans = 0;
        for (int right = 0; right < nums.length; right++) {
            freq.put(nums[right], freq.getOrDefault(nums[right], 0) + 1);
            while (freq.size() > m) {
                int count = freq.get(nums[left]) - 1;
                if (count == 0) {
                    freq.remove(nums[left]);
                } else {
                    freq.put(nums[left], count);
                }
                left++;
            }
            ans += right - left + 1;
        }
        return ans;
    }
}

